import { readSupervisorPDF } from '/pdf-import.js';
const $ = (selector, parent=document) => parent.querySelector(selector);
const $$ = (selector, parent=document) => [...parent.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z',
  team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 7.75',
  box:'m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9v10M3 8l9 4 9-4M7.5 5.5l9 5',
  audit:'M9 3H5v18h14V3h-4M9 2h6v4H9V2Zm-2 9h10M7 15h10',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-3-5h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',
  clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9Zm-8 12a2 2 0 0 0 4 0',
  plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',
  arrow:'m9 5 7 7-7 7',search:'M21 21l-6-6m2-5a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
  upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',camera:'M8 5l2-3h4l2 3h5v15H3V5h5Zm8 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  edit:'m16 3 5 5-12 12-6 1 1-6L16 3Zm-3 3 5 5',download:'M12 3v13m-5-5 5 5 5-5M3 18v3h18v-3',
  flag:'M5 22V3c6-4 8 4 15 0v10c-7 4-9-4-15 0',logout:'M9 3H3v18h6m5-14 5 5-5 5m-7-5h12',
  refresh:'M20 7v5h-5M4 17v-5h5M6 5a8 8 0 0 1 14 7M4 12a8 8 0 0 0 14 7',file:'M14 2H4v20h16V8l-6-6Zm0 0v6h6M8 12h8M8 16h8'
};
function icon(name) {return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;}
let state={events:[],users:[],rules:[],notifications:[],audit:[],settings:{timezone:'America/Chicago'}};
let session={user:null,csrf:null}, page='today', mode='events', date='', search='', filter='all', modal=null, stream=null, live=false, busy=false, toastTimer, serverOffset=0, previousFocus=null;
const app=$('#app'), modalRoot=$('#modal-root');
const timezone=()=>state.settings.timezone || session.timezone || 'America/Chicago';
const currentTime=()=>Date.now()+serverOffset;
function parts(value,zone=timezone()) {return Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).map(p=>[p.type,p.value]));}
function localDate(value) {const p=parts(value);return `${p.year}-${p.month}-${p.day}`;}
function localTime(value) {const p=parts(value);return `${p.hour}:${p.minute}`;}
function time(value) {return new Intl.DateTimeFormat('en-US',{timeZone:timezone(),hour:'numeric',minute:'2-digit'}).format(new Date(value));}
function dateTime(value) {return new Intl.DateTimeFormat('en-US',{timeZone:timezone(),month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value));}
function venueISO(day,clock) {
  if(!day || !clock) throw new Error('Enter the event date and start time.');
  const wanted=Date.parse(`${day}T${clock}:00Z`);let guess=wanted;
  for(let i=0;i<4;i++){const p=parts(guess);const observed=Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:00Z`);const difference=wanted-observed;if(!difference)break;guess+=difference;}
  if(localDate(guess)!==day || localTime(guess)!==clock)throw new Error('This time does not exist in the venue timezone due to daylight saving. Choose another time.');
  return new Date(guess).toISOString();
}
function initials(name) {return String(name).split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function avatar(user) {return `<span class="avatar" title="${esc(user?.name||'Unassigned')}">${esc(initials(user?.name||'?'))}</span>`;}
function teamFor(event) {return event.assignees.map(id=>state.users.find(u=>u.id===id)).filter(Boolean);}
function ready(event) {return event.equipment.length>0 && event.equipment.every(i=>i.ready===i.required);}
function progress(event) {const total=event.equipment.length,done=event.equipment.filter(i=>i.ready===i.required).length;return {done,total,percent:total?Math.round(done/total*100):0};}
function deadline(event) {return new Date(new Date(event.start).getTime()-3600000);}
function eventStatus(event) {if(event.completion)return {text:'Setup complete',class:'green'};if(deadline(event)<currentTime())return {text:'Setup overdue',class:'red'};if(ready(event))return {text:'Photo required',class:'amber'};if(event.equipment.some(i=>i.ready>0))return {text:'In progress',class:'amber'};return {text:event.assignees.length?'Not started':'Unassigned',class:'gray'};}
function countdown(event) {if(event.completion)return 'Ready for the event';const diff=deadline(event)-currentTime(),minutes=Math.ceil(Math.abs(diff)/60000);const span=minutes>=60?`${Math.floor(minutes/60)}h ${minutes%60}m`:`${minutes}m`;return diff<=0?`${span} overdue`:`${span} to setup deadline`;}
function isAdmin() {return session.user?.role==='supervisor';}
function toast(message,error=false) {clearTimeout(toastTimer);const target=$('#toast');target.textContent=message;target.className=`show${error?' error':''}`;toastTimer=setTimeout(()=>target.className='',6000);}
async function api(path,options={}) {
  const headers={...options.headers};if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}if(options.method && options.method!=='GET')headers['X-CSRF-Token']=session.csrf||'';
  const response=await fetch(path,{...options,headers});const serverDate=response.headers.get('date');if(serverDate)serverOffset=new Date(serverDate).getTime()-Date.now();
  const result=await response.json();if(!response.ok){if(response.status===401 && session.user){session.user=null;disconnect();closeModal(true);renderLogin();}if(response.status===409 && session.user)await loadState(false);throw new Error(result.error||'Request failed.');}return result;
}
async function loadState(draw=true) {const next=await api('/api/state');state=next;session.user=next.user;if(draw){render();if(modal?.type==='detail')renderDetail();}}
function connect() {
  disconnect();stream=new EventSource('/api/stream');stream.addEventListener('connected',()=>{live=true;updateLive();});stream.addEventListener('refresh',()=>loadState().catch(()=>{live=false;updateLive();}));stream.onerror=()=>{live=false;updateLive();};
}
function disconnect(){stream?.close();stream=null;live=false;}
function updateLive() {const node=$('[data-live]');if(node){node.className=`live${live?'':' offline'}`;node.textContent=live?'Live updates':'Reconnecting';}}
function bootAuth(){date ||= localDate(currentTime());render();connect();}
function navButton(id,label,name){return `<button class="${page===id?'active':''}" data-act="navigate" data-page="${id}" aria-current="${page===id?'page':'false'}">${icon(name)}<span>${label}</span></button>`;}
function render() {
  if(!session.user)return renderLogin();
  const unread=state.notifications.filter(n=>!n.read).length;
  app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">B</span><div><strong>Banquet<br>Steward</strong><small>READY FOR EVERY EVENT</small></div></div><nav class="nav" aria-label="Main navigation">${navButton('today',isAdmin()?'Overview':'My events','calendar')}${isAdmin()?navButton('team','Stewards','team')+navButton('equipment','Equipment rules','box')+navButton('audit','Audit log','audit'):''}${navButton('settings',isAdmin()?'Team & settings':'Account','settings')}</nav><div class="sidebar-bottom"><div class="venue">Banquet operations<small>${esc(timezone())} · setup 1 hour early</small></div><div class="user-pill">${avatar(session.user)}<div><strong>${esc(session.user.name)}</strong><small>${isAdmin()?'Supervisor':'Steward'}</small></div></div><button class="signout" data-act="logout">${icon('logout')} Sign out</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Operations / ${esc({today:'Daily overview',team:'Steward assignments',equipment:'Equipment mapping',audit:'Setup audit log',settings:'Team & settings'}[page])}</div><div class="mobile-brand"><span class="brand-icon">B</span>Banquet Steward</div><div class="top-actions"><span class="live${live?'':' offline'}" data-live>${live?'Live updates':'Connecting'}</span><button class="icon-button" data-act="notifications" aria-label="Notifications${unread?`, ${unread} unread`:''}">${icon('bell')}${unread?`<span class="notification-dot">${unread}</span>`:''}</button></div></header><div id="page-content">${pageContent()}</div></main></div>`;
  updateClocks();
}
function heading(title,subtitle,actions='') {return `<div class="page-heading"><div><div class="eyebrow muted" style="margin-bottom:10px">BANQUET OPERATIONS</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function selectedEvents() {return state.events.filter(e=>localDate(e.start)===date && (mode!=='mine'||e.assignees.includes(session.user.id))).sort((a,b)=>new Date(a.start)-new Date(b.start)||a.beo.localeCompare(b.beo));}
function stats(events) {const complete=events.filter(e=>e.completion).length,overdue=events.filter(e=>!e.completion&&deadline(e)<currentTime()).length,active=events.filter(e=>!e.completion&&e.equipment.some(i=>i.ready>0)).length;return `<div class="stats">${[[events.length,'Events today','Across all assigned rooms','calendar',''],[active,'In progress','Equipment setup underway','box',''],[complete,'Setup complete','Photo confirmation recorded','check','good'],[overdue,'Overdue setups','Past the setup deadline','clock','alert']].map(([v,l,n,i,c])=>`<div class="stat ${c}"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value">${v.toString().padStart(2,'0')}</div><div class="stat-note">${n}</div></div>`).join('')}</div>`;}
function empty(title,description,action='',name='calendar') {return `<div class="empty">${icon(name)}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function pageContent() {
  if(page==='today')return todayPage();if(page==='team')return teamPage();if(page==='equipment')return equipmentPage();if(page==='audit')return auditPage();return settingsPage();
}
function todayPage() {
  const events=selectedEvents(),filtered=events.filter(e=>(filter==='all'||filter==='open'&&!e.completion||filter==='complete'&&e.completion||filter==='overdue'&&!e.completion&&deadline(e)<currentTime())&&`${e.beo} ${e.name} ${e.room} ${e.type}`.toLowerCase().includes(search.toLowerCase()));
  const today=localDate(currentTime());const dayLabel=new Intl.DateTimeFormat('en-US',{timeZone:timezone(),weekday:'long',month:'long',day:'numeric'}).format(new Date(venueISO(date,'12:00')));
  return heading(isAdmin()?'Every setup, in view.':`Your day, ${esc(session.user.name.split(' ')[0])}.`,`${esc(dayLabel)} · Setups due one hour before event start`,isAdmin()?`<button class="button secondary" data-act="new-event">${icon('plus')} Add event</button><button class="button" data-act="import">${icon('upload')} Import BEO</button>`:'')+stats(events)+`<div class="toolbar"><div class="toolbar-group">${isAdmin()?`<div class="tabs" aria-label="Event view"><button class="${mode==='events'?'active':''}" data-act="mode" data-mode="events">All events</button><button class="${mode==='stewards'?'active':''}" data-act="mode" data-mode="stewards">By steward</button><button class="${mode==='mine'?'active':''}" data-act="mode" data-mode="mine">My events</button></div>`:`<span class="eyebrow muted">MY ASSIGNED EVENTS</span>`}<label class="visually-hidden" for="event-date">Event date</label><input type="date" id="event-date" value="${esc(date)}" data-date></div><div class="toolbar-group filters"><div class="search">${icon('search')}<label class="visually-hidden" for="event-search">Search events</label><input id="event-search" value="${esc(search)}" placeholder="Search BEO, event or room" data-search></div><label class="visually-hidden" for="event-filter">Filter by status</label><select id="event-filter" data-filter>${[['all','All statuses'],['open','Outstanding'],['overdue','Overdue'],['complete','Complete']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select></div></div>${mode==='stewards'&&isAdmin()?teamCards(filtered):`<div class="section-label"><span>${date===today?'Today’s event schedule':'Event schedule'}</span><small>${filtered.length} event${filtered.length===1?'':'s'} · ordered by start time</small></div><div class="event-list">${filtered.length?filtered.map(eventCard).join(''):empty(state.events.length?'No events match this view':'Your next event starts here',state.events.length?'Try another day or status. Assigned events will appear here as soon as your supervisor adds them.':isAdmin()?'Import a BEO, review its details and assign the setup team. Your equipment checklist will be calculated from your rules.':'Your supervisor will import the BEO and assign your events. Your equipment checklists will appear here automatically.',isAdmin()?'<button class="button" data-act="import">Import your first BEO</button>':'')}</div>`}<p class="footer-note">Countdowns target the setup deadline, one hour before the event. Equipment changes and BEO revisions appear in notifications.</p>`;
}
function eventCard(event) {
  const p=progress(event),s=eventStatus(event),outstanding=event.equipment.filter(i=>i.ready<i.required);return `<article class="event-card ${s.class==='red'?'urgent':''}" tabindex="0" role="button" data-act="event" data-id="${esc(event.id)}" aria-label="BEO ${esc(event.beo)}, ${esc(event.name)}, ${time(event.start)}, ${esc(s.text)}"><div class="event-time"><strong>${esc(time(event.start).replace(/ [AP]M/,''))}</strong><small>${esc(time(event.start).match(/[AP]M/)?.[0]||'')}<br>EVENT START</small></div><div class="event-info"><div class="beo">BEO #${esc(event.beo)} ${event.revision?` · REV ${event.revision}`:''}</div><h3 class="event-title">${esc(event.name)}</h3><div class="event-meta"><span>${icon('pin')} ${esc(event.room)}</span><span>${event.guests} guests</span><span>${esc(event.type)}</span></div><div class="avatars">${teamFor(event).map(avatar).join('')}${event.assignees.length?'':`<small class="muted">No steward assigned</small>`}</div></div><div class="event-progress"><div class="progress-top"><span>Equipment ready</span><strong>${p.done} / ${p.total}</strong></div><div class="progress-track"><span style="width:${p.percent}%"></span></div><div class="progress-bottom">${outstanding.length?`${esc(outstanding.slice(0,2).map(i=>`${i.required-i.ready} ${i.name.toLowerCase()}`).join(' · '))}${outstanding.length>2?' + more':''}`:event.completion?'Photo & audit saved':'All items ready · photo needed'}</div></div><div class="event-status"><span class="badge ${s.class}">${s.class==='green'?icon('check'):''}${s.text}</span><span class="countdown ${s.class==='red'?'late':''}" data-countdown="${esc(event.id)}">${countdown(event)}</span><small>Setup by ${time(deadline(event))}</small></div>${icon('arrow')}</article>`;
}
function teamCards(events) {
  const team=state.users.filter(u=>u.active&&u.role==='steward');if(!team.length)return empty('Build your setup team','Create individual steward accounts, then assign one or more people to each event.','<button class="button" data-act="add-user">Add a steward</button>','team');
  return `<div class="team-grid">${team.map(user=>{const assigned=events.filter(e=>e.assignees.includes(user.id)),complete=assigned.filter(e=>e.completion).length,late=assigned.filter(e=>!e.completion&&deadline(e)<currentTime()).length;return `<div class="team-card"><div class="team-head">${avatar(user)}<div><h3>${esc(user.name)}</h3><span class="muted" style="font-size:11px">${assigned.length?`${new Set(assigned.map(e=>e.room)).size} room(s) today`:'Available for assignment'}</span></div></div><div class="team-metrics"><div><strong>${assigned.length}</strong><small>Assigned</small></div><div><strong>${complete}</strong><small>Complete</small></div><div><strong style="color:${late?'var(--red)':'inherit'}">${late}</strong><small>Overdue</small></div></div>${assigned.map(e=>{const s=eventStatus(e);return `<div class="mini-event" tabindex="0" role="button" data-act="event" data-id="${e.id}"><div><strong>${time(e.start)} · ${esc(e.name)}</strong><small>BEO ${esc(e.beo)} · ${esc(e.room)} · ${progress(e).done}/${e.equipment.length} ready</small></div><span class="badge ${s.class}">${s.text}</span></div>`;}).join('')||'<p class="muted" style="font-size:12px">No events assigned for this date.</p>'}</div>`;}).join('')}</div>`;
}
function teamPage() {return heading('A team in the right place.','See every steward’s workload, rooms and outstanding setups.',`<button class="button" data-act="add-user">${icon('plus')} Add steward</button>`)+`<div class="toolbar"><span class="eyebrow muted">DAILY WORKLOAD</span><input type="date" aria-label="Team event date" data-date value="${date}"></div>`+teamCards(selectedEvents());}
function ruleDescription(r) {return r.basis==='fixed'?`${r.quantity} per event`:r.basis==='dishes'?`${r.quantity} per hot buffet dish`:`${r.quantity} per ${r.per} guest${r.per===1?'':'s'} · round up`;}
function equipmentPage() {return heading('The right kit, every time.','Maintain the equipment mapping used when creating event checklists.',`<button class="button secondary" data-act="import-rules">${icon('upload')} Import CSV</button><button class="button" data-act="add-rule">${icon('plus')} Add rule</button>`)+`<div class="notice warning">${icon('flag')}<span>Starting rules are examples. Confirm your venue’s requirements before using them. Chafers are based on hot buffet dishes; guest-based rules round up. Rule edits affect new events. Recalculate an existing event explicitly to alert its stewards.</span></div><div class="panel table-wrap"><table><thead><tr><th>Equipment</th><th>Event type contains</th><th>Quantity rule</th><th>Unit</th><th>Actions</th></tr></thead><tbody>${state.rules.map(r=>`<tr><td><strong>${esc(r.name)}</strong>${r.note?`<div class="rule-note">${esc(r.note)}</div>`:''}</td><td><span class="badge gray">${esc(r.eventType==='*'?'All events':r.eventType)}</span></td><td>${ruleDescription(r)}</td><td>${esc(r.unit)}</td><td><div class="row-actions"><button class="button secondary small" data-act="edit-rule" data-id="${r.id}">Edit</button><button class="button ghost small" data-act="delete-rule" data-id="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('close')}</button></div></td></tr>`).join('')||'<tr><td colspan="5">No equipment rules yet. Add a rule or import a CSV.</td></tr>'}</tbody></table></div><button class="button secondary" data-act="export-rules">${icon('download')} Export rules CSV</button><p class="footer-note">CSV columns: name, eventType, basis, quantity, per, unit, note. Basis is fixed, guests or dishes. Use * to match every event type.</p>`;}
function auditPage() {
  const list=state.audit.filter(a=>`${a.action} ${a.actor_name} ${JSON.stringify(a.detail)}`.toLowerCase().includes(search.toLowerCase()));
  return heading('A record of every setup.','Completion photos, equipment changes and BEO revisions, attributed to your team.',`<button class="button secondary" data-act="export-audit">${icon('download')} Export JSON</button>`)+`<div class="toolbar"><div class="search">${icon('search')}<input aria-label="Search audit log" value="${esc(search)}" data-search placeholder="Search BEO, user or action"></div><small class="muted">Most recent ${state.audit.length} records · up to 500</small></div><div class="panel">${list.map(a=>{const event=state.events.find(e=>e.id===a.event_id);return `<div class="audit-entry">${avatar({name:a.actor_name})}<div style="flex:1;min-width:0"><h3>${esc(a.action)}</h3><p>${esc(a.actor_name)} ${event?`· BEO ${esc(event.beo)} · ${esc(event.room)}`:''}</p>${a.action==='Equipment progress updated'?`<small>${esc(a.detail.item)}: ${a.detail.before} → ${a.detail.after} of ${a.detail.required}</small>`:''}${a.detail.completion?.photoId?`<a href="/api/files/${esc(a.detail.completion.photoId)}" target="_blank" rel="noopener"><img class="photo-thumb" src="/api/files/${esc(a.detail.completion.photoId)}" alt="Setup completion photo"></a>`:''}<details style="margin-top:10px;font-size:11px"><summary>View record</summary><pre class="details-json">${esc(JSON.stringify(a.detail,null,2))}</pre></details></div><div class="audit-time">${dateTime(a.time)}</div></div>`;}).join('')||'<p class="muted">No audit records match this view.</p>'}</div>`;
}
function settingsPage() {
  if(!isAdmin())return heading('Your account.','Your checklist actions are attributed to this account.')+`<div class="panel"><div class="team-head">${avatar(session.user)}<div><h3>${esc(session.user.name)}</h3><small class="muted">${esc(session.user.email)} · Steward</small></div></div><p class="muted" style="font-size:13px">Ask your supervisor to reset your password or update your account.</p><button class="button secondary" data-act="logout">${icon('logout')} Sign out</button></div>`;
  return heading('Keep your operation ready.','Manage individual accounts and venue settings.',`<button class="button" data-act="add-user">${icon('plus')} Add team member</button>`)+`<div class="panel table-wrap"><h3>Team accounts</h3><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong>${u.id===session.user.id?'<small class="muted">Your account</small>':''}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td><span class="badge ${u.active?'green':'gray'}">${u.active?'Active':'Inactive'}</span></td><td>${u.id!==session.user.id?`<button class="button secondary small" data-act="edit-user" data-id="${u.id}">Manage</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="split-settings"><form class="panel" id="timezone-form"><h3>Venue timezone</h3><p class="muted" style="font-size:12px">All event times and countdowns use the venue timezone, regardless of a phone’s settings.</p>${field('timezone','Timezone',timezone())}<button class="button" style="margin-top:15px" type="submit">Save timezone</button></form><div class="panel"><h3>Setup & completion</h3><p class="muted" style="font-size:12px">Setup deadline: <strong>1 hour before event start</strong><br>Completion photo: <strong>Required</strong><br>Shared checklist: <strong>Multiple stewards supported</strong><br>Accounts: <strong>Supervisor-managed</strong></p><p class="footer-note">On iPhone, open this app in Safari, tap Share, then Add to Home Screen. A hosted HTTPS URL is required for team access.</p></div></div><button class="button secondary" data-act="logout">${icon('logout')} Sign out</button>`;
}
function renderLogin() {
  const setup=session.setupRequired;app.innerHTML=`<div class="login-layout"><section class="login-story"><div class="brand"><span class="brand-icon">B</span><div><strong>Banquet Steward</strong><small>READY FOR EVERY EVENT</small></div></div><div><h1>Every room.<br>Every detail.<br><span>Ready on time.</span></h1><p>Your team’s daily banquet setups, together in one place.</p><div class="story-list"><div>${icon('calendar')} Events in time order, with setup countdowns</div><div>${icon('box')} Equipment checklists that update together</div><div>${icon('camera')} Photo confirmation and a clear audit trail</div></div></div><div class="story-footer">Built for the people behind every great event.</div></section><section class="login-form-wrap"><form class="login-form" id="auth-form"><div class="eyebrow muted" style="margin-bottom:14px">${setup?'INITIAL SETUP':'WELCOME BACK'}</div><h2>${setup?'Set up your operation.':'Sign in to your day.'}</h2><p>${setup?'Create the first supervisor account. You can add stewards once you’re signed in.':'Use the individual account provided by your supervisor.'}</p>${setup?field('name','Your full name','','text','required autocomplete="name"'):''}${field('email','Email address','','email','required autocomplete="username"')}${field('password',setup?'Create a password':'Password','','password',`required ${setup?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'}`)}${setup?'<p style="font-size:11px;margin-top:-10px">Use at least 12 characters.</p>'+field('token','Server setup token (if configured)','','password','autocomplete="off"'):''}<div class="error-message" id="auth-error" role="alert"></div><button class="button" type="submit">${setup?'Create supervisor account':'Sign in'}${icon('arrow')}</button><p style="font-size:11px;margin-top:22px">${setup?'Initial setup is available locally, or with a server bootstrap token.':'Need access or a password reset? Contact your supervisor.'}</p></form></section></div>`;
}
function field(name,label,value='',type='text',extra='',help='') {return `<div class="field"><label for="field-${name}">${esc(label)}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${help?`<small>${help}</small>`:''}</div>`;}
function selectField(name,label,options,value) {return `<div class="field"><label for="field-${name}">${esc(label)}</label><select id="field-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function setModal(content,wide=false) {
  if(!modalRoot.firstChild)previousFocus=document.activeElement;
  modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</section></div>`;app.inert=true;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal-head button',modalRoot)?.focus());
}
function modalHead(title,subtitle='',eyebrow='') {return `<header class="modal-head"><div>${eyebrow?`<div class="eyebrow muted">${eyebrow}</div>`:''}<h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-act="close-modal" aria-label="Close dialog">${icon('close')}</button></header>`;}
function closeModal(force=false){if(busy&&!force)return;modalRoot.innerHTML='';modal=null;app.inert=false;document.body.style.overflow='';previousFocus?.focus();}
function openEvent(id){modal={type:'detail',id};renderDetail();}
function renderDetail() {
  const event=state.events.find(e=>e.id===modal.id);if(!event){closeModal();return;}
  const p=progress(event),s=eventStatus(event),complete=event.completion;
  const latestChange=state.notifications.find(n=>n.event_id===event.id&&!n.read);
  const changeNotice=latestChange?`<div class="notice warning">${icon('bell')}<span style="flex:1">${esc(latestChange.message)}<br><button class="button ghost small" data-act="acknowledge-change" data-id="${esc(latestChange.id)}">Mark this update reviewed</button></span></div>`:'';
  setModal(modalHead(esc(event.name),`${esc(event.room)} · ${esc(event.type)} · ${event.guests} guests`,`BEO #${esc(event.beo)}${event.revision?` · REVISION ${event.revision}`:''}`)+`<div class="modal-body">${changeNotice}<div class="detail-summary"><div><small>EVENT START</small><strong>${time(event.start)}</strong><small style="margin-top:6px">${localDate(event.start)}</small></div><div><small>SETUP DEADLINE</small><strong>${time(deadline(event))}</strong><small style="margin-top:6px" data-countdown="${event.id}">${countdown(event)}</small></div><div><small>EQUIPMENT READY</small><strong>${p.done} / ${p.total} types</strong><small style="margin-top:6px"><span class="badge ${s.class}">${s.text}</span></small></div></div>${event.notes?`<div class="notice">${icon('file')}<span>${esc(event.notes)}</span></div>`:''}${complete?`<div class="notice">${icon('check')}<span>Completed by <strong>${esc(complete.userName)}</strong> · ${dateTime(complete.time)}. <a href="/api/files/${complete.photoId}" target="_blank" rel="noopener">View setup photo</a></span></div>`:''}<div class="section-label"><span>Required equipment</span>${isAdmin()?`<button class="button ghost small" data-act="edit-equipment" data-id="${event.id}">${icon('edit')} Adjust</button>`:''}</div><div class="checklist">${event.equipment.map(item=>`<div class="check-row ${item.ready===item.required?'checked':''}"><input type="checkbox" aria-label="Mark ${esc(item.name)} ready" data-check-item="${item.id}" data-event="${event.id}" ${item.ready===item.required?'checked':''} ${complete||busy?'disabled':''}><div class="check-info"><strong>${esc(item.name)}</strong><small>${item.updatedBy?`Last updated by ${esc(item.updatedBy.name)} · ${time(item.updatedBy.time)}`:`${item.basis==='dishes'?'Based on hot buffet dishes':item.basis==='guests'?'Based on guest count':item.basis==='manual'?'Supervisor adjustment':'Fixed requirement'}`}</small></div><label class="visually-hidden" for="qty-${item.id}">Ready ${esc(item.name)} quantity</label><input id="qty-${item.id}" class="quantity-input" type="number" inputmode="numeric" min="0" max="${item.required}" value="${item.ready}" data-ready-item="${item.id}" data-event="${event.id}" ${complete||busy?'disabled':''}><span class="check-quantity">/ ${item.required}<br>${esc(item.unit)}</span></div>`).join('')}</div><div class="detail-team"><span class="muted" style="font-size:11px">Assigned team</span>${teamFor(event).map(u=>`<span class="team-chip">${avatar(u)}${esc(u.name)}${u.active?'':' (inactive)'}</span>`).join('')||'<span class="muted" style="font-size:11px">Unassigned</span>'}</div>${event.dishes.length?`<p class="muted" style="font-size:11px">Hot buffet dishes: ${esc(event.dishes.join(' · '))}</p>`:''}${isAdmin()?`<div class="detail-actions"><button class="button secondary small" data-act="edit-event" data-id="${event.id}">${icon('team')} Details & assignments</button><button class="button secondary small" data-act="import" data-id="${event.id}">${icon('upload')} Import revised BEO</button>${event.sourceFile?`<a class="button secondary small" href="/api/files/${event.sourceFile}" target="_blank" rel="noopener">${icon('file')} Original BEO</a>`:''}</div>`:''}</div><footer class="modal-footer"><button class="button secondary" data-act="close-modal">Close</button>${!complete?`<button class="button" data-act="complete" data-id="${event.id}" ${ready(event)?'':'disabled'}>${icon('camera')} ${ready(event)?'Confirm setup & take photo':'Complete all equipment first'}</button>`:''}</footer>`);
}
function openImport(eventId=null) {modal={type:'import',eventId};setModal(modalHead(eventId?'Import revised BEO':'Import a BEO','One event and room per BEO. All PDF pages will be read.')+`<form id="pdf-form"><div class="modal-body"><label class="upload-zone">${icon('upload')}<strong>Choose your BEO PDF</strong><small>Multi-page PDFs supported · up to 10 MB · up to 40 pages</small><input type="file" name="file" accept="application/pdf,.pdf" required></label><div class="notice warning" style="margin-top:18px">${icon('flag')}<span>You’ll review the BEO number, room, time, guest count and buffet dishes before saving. Scanned pages use OCR and need careful review.</span></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit">Read all pages ${icon('arrow')}</button></footer></form>`);}
function editorModel(event=null,imported=null) {
  const fields=imported?.fields||{};return {beo:fields.beo||event?.beo||'',name:fields.name||event?.name||'',room:fields.room||event?.room||'',zone:event?.zone||'',type:fields.type||event?.type||(imported?'':'Lunch buffet'),guests:fields.guests||event?.guests||(imported?'':100),start:event?.start||null,dishes:event?.dishes||[],assignees:event?.assignees||[],notes:event?.notes||''};
}
async function openEditor(event=null,imported=null) {
  if(imported?.existing && !event)event=imported.existing;
  modal={type:'editor',event,imported,model:editorModel(event,imported)};renderEditor();
  if(event){try{const result=await api(`/api/events/${event.id}/suggestions`);if(modal?.type==='editor'&&modal.event?.id===event.id)renderSuggestions(result.suggestions);}catch(e){toast(e.message,true);}}
}
function renderEditor() {
  const {event,imported,model}=modal;const revision=!!event&&!!imported;
  const stewardList=state.users.filter(u=>u.active);
  setModal(modalHead(revision?'Review BEO revision':event?'Event details & assignments':'Review event details',revision?'Compare the imported document, then confirm the changes.':`Enter event times in ${esc(timezone())}.`,event?`BEO #${esc(event.beo)} · VERSION ${event.version}`:imported?`${imported.pages} PAGE${imported.pages===1?'':'S'} READ${imported.ocr?' · OCR USED':''}`:'NEW EVENT')+`<form id="event-form"><div class="modal-body">${imported?`<div class="notice ${imported.fields.multipleBEOs?'error':'warning'}">${icon('flag')}<span>${imported.fields.multipleBEOs?`Multiple BEO numbers detected (${esc(imported.fields.detectedBEOs.join(', '))}). Upload a PDF containing only one BEO.`:`${imported.fields.revision?'Revision marking detected. ':''}Extraction is a draft. Confirm every field against the PDF, including all pages. ${imported.fields.dateHint?`Date found: ${esc(imported.fields.dateHint)}. `:''}${imported.fields.timeHint?`Time found: ${esc(imported.fields.timeHint)}.`:''}`}</span></div>`:''}${revision?`<div class="notice">${icon('refresh')}<span>Updating existing BEO <strong>${esc(event.beo)}</strong>. Current: ${esc(event.room)}, ${event.guests} guests, ${dateTime(event.start)}. Applied changes will alert the assigned team and retain the previous version.</span></div>`:''}<div class="${imported?'source-review':''}"><div><div class="form-grid">${field('beo','BEO number',model.beo,'text',`required ${event?'readonly':''}`)}${field('name','Event name',model.name,'text','required')}${field('room','Room',model.room,'text','required')}${field('zone','Location / floor',model.zone,'text','','Used to suggest nearby stewards.')}${field('type','Event type',model.type,'text','required')}${field('guests','Guest count',model.guests,'number','required min="1" max="100000" step="1"')}${field('date','Event date',model.start?localDate(model.start):(imported?'':date),'date','required')}${field('time','Event start time',model.start?localTime(model.start):(imported?'':'12:00'),'time','required')}<div class="field full"><label for="field-dishes">Hot buffet dishes — one per line</label><textarea name="dishes" id="field-dishes" placeholder="Roasted chicken&#10;Braised beef&#10;Vegetable casserole">${esc(model.dishes.join('\n'))}</textarea><small>List dishes that need chafers. Cold items do not count toward the chafer rule.</small></div><div class="field full"><label for="field-notes">Setup notes</label><textarea name="notes" id="field-notes" maxlength="2000" placeholder="Special instructions for the setup team">${esc(model.notes)}</textarea></div></div></div>${imported?`<div><div class="section-label" style="margin-top:0"><span>Extracted document · ${imported.pages} pages</span><a href="/api/files/${esc(imported.fileId)}" target="_blank" rel="noopener" style="font-size:11px">Open PDF</a></div><pre class="source-text">${esc(imported.text)}</pre></div>`:''}</div><div id="equipment-preview"></div><div class="section-label"><span>Assign setup team</span><button class="button secondary small" type="button" data-act="suggest">${icon('team')} Suggest stewards</button></div><p class="muted" style="font-size:11px">Suggestions favor the same room and nearby locations, then account for workload. Select any number of team members; your selection controls the assignment.</p><div class="suggestions" id="suggestions">${stewardList.map(u=>`<label class="suggestion"><input type="checkbox" name="assignees" value="${u.id}" ${model.assignees.includes(u.id)?'checked':''}>${avatar(u)}<span><strong>${esc(u.name)}</strong><small>${esc(u.role)}</small></span></label>`).join('')||'<div class="notice warning">Add team accounts in Team & settings to assign stewards. You can save an event unassigned.</div>'}</div>${event?`<label style="display:flex;align-items:flex-start;gap:10px;margin-top:20px"><input type="checkbox" name="recalculate" ${revision?'checked':''}><span>Recalculate equipment from current rules<small class="muted" style="display:block;font-weight:400;margin-top:5px">Replaces event-specific overrides. Unchanged rule items retain ready quantities; new requirements remain outstanding.</small></span></label>${event.completion?'<label style="display:flex;align-items:center;gap:10px;margin-top:15px"><input type="checkbox" name="reopen">Reopen setup for verification</label>':''}`:''}<div class="notice" style="margin-top:20px">${icon('clock')}<span id="deadline-preview">Setup deadline is one hour before event start. A completion photo will be required.</span></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit" ${imported?.fields.multipleBEOs?'disabled':''}>${revision?'Apply revision & alert team':event?'Save & alert team':'Create event & checklist'}</button></footer></form>`,!!imported);
  updateDeadlinePreview();
}
function eventFormBody(form) {const f=new FormData(form);return {beo:String(f.get('beo')).trim(),name:String(f.get('name')).trim(),room:String(f.get('room')).trim(),zone:String(f.get('zone')).trim(),type:String(f.get('type')).trim(),guests:Number(f.get('guests')),start:venueISO(String(f.get('date')),String(f.get('time'))),dishes:String(f.get('dishes')).split('\n').map(d=>d.trim()).filter(Boolean),notes:String(f.get('notes')),assignees:f.getAll('assignees'),recalculate:f.get('recalculate')==='on',reopen:f.get('reopen')==='on',fileId:modal.imported?.fileId||null,revision:!!modal.imported?.fields.revision,version:modal.event?.version};}
function updateDeadlinePreview(){
  const form=$('#event-form');if(!form)return;
  try {
    const body=eventFormBody(form);
    $('#deadline-preview').textContent=`Setup deadline: ${time(new Date(new Date(body.start).getTime()-3600000))} · ${timezone()}. Completion photo required.`;
    const old=modal.event;
    const normalize=value=>String(value).toLowerCase().replace(/buffett/g,'buffet');
    const items=old&&!body.recalculate?old.equipment:state.rules.filter(r=>r.eventType==='*'||normalize(body.type).includes(normalize(r.eventType))).map(r=>({name:r.name,unit:r.unit,required:r.quantity*(r.basis==='guests'?Math.ceil(body.guests/r.per):r.basis==='dishes'?body.dishes.length:1)})).filter(r=>r.required>0);
    const changes=old?['room','type','guests','start','dishes','notes'].filter(k=>JSON.stringify(body[k])!==JSON.stringify(old[k])).map(k=>`${k==='start'?'Start time':k==='dishes'?'Hot dishes':k[0].toUpperCase()+k.slice(1)}: ${k==='start'?dateTime(old[k]):esc(Array.isArray(old[k])?old[k].join(', '):old[k])} → ${k==='start'?dateTime(body[k]):esc(Array.isArray(body[k])?body[k].join(', '):body[k])}`):[];
    $('#equipment-preview').innerHTML=`<div class="section-label"><span>${old&&!body.recalculate?'Current equipment requirements':'Calculated equipment preview'}</span></div><div class="checklist">${items.map(i=>`<div class="check-row" style="padding:12px 16px;font-size:12px"><span style="flex:1">${esc(i.name)}</span><strong>${i.required} ${esc(i.unit)}</strong></div>`).join('')||'<div class="check-row muted" style="font-size:12px">No calculated items yet. Confirm the event type, guest count and hot dishes, and add matching equipment rules.</div>'}</div>${changes.length?`<div class="notice warning" style="margin-top:16px"><span><strong>Changes to review</strong><br>${changes.join('<br>')}${body.recalculate?'<br>Equipment will be recalculated from current rules.':''}</span></div>`:''}`;
  } catch {const preview=$('#equipment-preview');if(preview)preview.innerHTML='';}
}
function renderSuggestions(suggestions){const form=$('#event-form');if(!form)return;const selected=new FormData(form).getAll('assignees');$('#suggestions').innerHTML=suggestions.map((s,i)=>`<label class="suggestion"><input type="checkbox" name="assignees" value="${s.user.id}" ${selected.includes(s.user.id)?'checked':''}>${avatar(s.user)}<span><strong>${esc(s.user.name)}</strong><small>${esc(s.reason)}</small></span>${i===0&&!s.overlaps?'<span class="badge green">Suggested</span>':s.overlaps?'<span class="badge amber">Time conflict</span>':''}</label>`).join('')+state.users.filter(u=>u.active&&u.role==='supervisor').map(u=>`<label class="suggestion"><input type="checkbox" name="assignees" value="${u.id}" ${selected.includes(u.id)?'checked':''}>${avatar(u)}<span><strong>${esc(u.name)}</strong><small>Supervisor</small></span></label>`).join('');}
function localSuggestions(body){return state.users.filter(u=>u.active&&u.role==='steward').map(user=>{const assigned=state.events.filter(e=>e.id!==modal.event?.id&&e.assignees.includes(user.id)&&localDate(e.start)===localDate(body.start));const sameRoom=assigned.filter(e=>e.room.toLowerCase()===body.room.toLowerCase()).length,sameZone=body.zone?assigned.filter(e=>e.zone?.toLowerCase()===body.zone.toLowerCase()).length:0,overlaps=assigned.filter(e=>!e.completion&&Math.abs(new Date(e.start)-new Date(body.start))<3600000).length,outstanding=assigned.filter(e=>!e.completion).length;return {user,overlaps,score:sameRoom*4+sameZone*2-outstanding*2-overlaps*8,reason:overlaps?`${overlaps} event(s) within an hour · review availability`:sameRoom?`${sameRoom} event(s) in this room · ${outstanding} open`:sameZone?`Already working in ${body.zone} · ${outstanding} open`:`${outstanding} open event(s) today`};}).sort((a,b)=>b.score-a.score||a.user.name.localeCompare(b.user.name));}
function openEquipment(id){const event=state.events.find(e=>e.id===id);modal={type:'equipment-edit',event};setModal(modalHead('Adjust required equipment',`BEO ${esc(event.beo)} · ${esc(event.name)}`)+`<form id="equipment-form"><div class="modal-body"><div class="notice warning">${icon('bell')}<span>Saving will notify every assigned steward. A completed setup will reopen for verification; its previous photo and completion stay in the audit log.</span></div><div class="equipment-edit-row muted" style="font-size:10px"><span>Equipment</span><span>Required</span><span>Unit</span><span></span></div><div id="equipment-rows">${event.equipment.map(equipmentEditRow).join('')}</div><button class="button secondary small" type="button" data-act="add-equipment-row">${icon('plus')} Add equipment</button><div class="field" style="margin-top:20px"><label for="change-reason">Reason for change</label><textarea name="reason" id="change-reason" placeholder="Guest count changed, an extra buffet station…"></textarea></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit">Save changes & alert team</button></footer></form>`);}
function equipmentEditRow(item={}) {return `<div class="equipment-edit-row" data-equipment-row data-id="${esc(item.id||'')}"><input name="equipment-name" aria-label="Equipment name" value="${esc(item.name||'')}" placeholder="Equipment" required><input name="equipment-required" aria-label="Required quantity" type="number" min="1" max="100000" step="1" value="${item.required||1}" required><input name="equipment-unit" aria-label="Equipment unit" value="${esc(item.unit||'each')}"><button class="button ghost small" type="button" data-act="remove-equipment-row" aria-label="Remove equipment">${icon('close')}</button></div>`;}
function openCompletion(id) {const event=state.events.find(e=>e.id===id);modal={type:'complete',event};setModal(modalHead('Ready to confirm setup?',`BEO ${esc(event.beo)} · ${esc(event.room)}`)+`<form id="complete-form"><div class="modal-body"><div class="notice">${icon('check')}<span>Every equipment item is ready. Take a clear photo showing the completed setup. Your name, server timestamp and photo will be saved in the supervisor audit log.</span></div><label class="upload-zone">${icon('camera')}<strong>Take the required setup photo</strong><small>Use your iPhone camera or choose a photo</small><input type="file" name="photo" accept="image/*" capture="environment" required id="completion-photo"></label><div id="photo-preview"></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="event" data-id="${id}">Back to checklist</button><button class="button" type="submit">${icon('check')} Mark setup complete</button></footer></form>`);}
async function compressPhoto(file){if(file.size>20*1024*1024)throw new Error('Choose a photo smaller than 20 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not prepare the photo.')), 'image/jpeg',.86));}
function openRule(id=null){const rule=state.rules.find(r=>r.id===id)||{eventType:'buffet',basis:'fixed',quantity:1,per:1,unit:'each'};modal={type:'rule',rule};setModal(modalHead(id?'Edit equipment rule':'Add equipment rule','Changes affect new events. Existing events require explicit recalculation.')+`<form id="rule-form"><div class="modal-body"><div class="form-grid">${field('name','Equipment name',rule.name,'text','required')}${field('eventType','Event type contains',rule.eventType,'text','required','','')}${selectField('basis','Quantity basis',[['fixed','Fixed per event'],['guests','Guest count'],['dishes','Hot buffet dishes']],rule.basis)}${field('quantity','Quantity',rule.quantity,'number','min="1" step="1" required')}${field('per','Per this many guests',rule.per,'number','min="1" step="1" required','Used only for guest-based rules. Rounds up.')}${field('unit','Unit',rule.unit,'text','required')}<div class="field full"><label for="field-note">Rule notes</label><textarea id="field-note" name="note">${esc(rule.note||'')}</textarea></div></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit">Save rule</button></footer></form>`);}
function openUser(id=null){const user=state.users.find(u=>u.id===id);modal={type:'user',user};setModal(modalHead(user?'Manage team account':'Add a team member','Each person uses their own login. Share passwords through your usual secure channel.')+`<form id="user-form"><div class="modal-body"><div class="form-grid">${field('name','Full name',user?.name,'text','required')}${field('email','Email address',user?.email,'email',`required ${user?'readonly':''}`)}${selectField('role','Access role',[['steward','Steward'],['supervisor','Supervisor']],user?.role||'steward')}${user?selectField('active','Account status',[['1','Active'],['0','Inactive']],user.active?'1':'0'):''}<div class="field full"><label for="user-password">${user?'Reset password (optional)':'Initial password'}</label><input id="user-password" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" ${user?'':'required'}><small>At least 12 characters. ${user?'Saving account changes signs this person out of existing sessions.':''}</small></div></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit">${user?'Save account':'Create account'}</button></footer></form>`);}
function openNotifications(){modal={type:'notifications'};setModal(modalHead('Your updates','Assignments, equipment changes and BEO revisions.')+`<div class="modal-body">${state.notifications.map(n=>`<button class="notification ${n.read?'':'unread'}" data-act="notification" data-id="${n.id}" data-event="${n.event_id}"><p>${esc(n.message)}</p><small>${dateTime(n.time)} · ${n.read?'Read':'Tap to review event'}</small></button>`).join('')||'<p class="muted" style="font-size:13px">No updates yet. You’ll be notified when your assignments or equipment change.</p>'}</div>`);}
function parseCSV(text){const records=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))records.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV has an unclosed quote.');row.push(cell);if(row.some(x=>x.trim()))records.push(row);return records;}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRules(){const keys=['name','eventType','basis','quantity','per','unit','note'];const cell=x=>`"${String(x??'').replace(/"/g,'""')}"`;download('equipment-rules.csv',[keys.join(','),...state.rules.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv');}
function openRuleImport(){modal={type:'rule-import'};setModal(modalHead('Import equipment rules','Imported rules are added to the existing table; review the preview first.')+`<form id="rule-import-form"><div class="modal-body"><div class="notice">${icon('file')}<span>Required CSV columns: name, eventType, basis, quantity, per, unit. Optional: note. Basis values: fixed, guests, dishes.</span></div><input name="file" type="file" accept=".csv,text/csv" required aria-label="Equipment rules CSV"><button type="button" class="button secondary small" data-act="download-template" style="margin-top:12px">Download CSV template</button><div id="rule-import-preview" style="margin-top:20px"></div><div class="error-message" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button secondary" type="button" data-act="close-modal">Cancel</button><button class="button" type="submit">Preview import</button></footer></form>`);}
async function saveChecklist(eventId,itemId,value){if(busy)return;busy=true;for(const input of $$('[data-check-item],[data-ready-item]'))input.disabled=true;try{const event=state.events.find(e=>e.id===eventId);await api(`/api/events/${eventId}/checklist`,{method:'PATCH',body:{version:event.version,itemId,ready:value}});await loadState(false);busy=false;render();renderDetail();const updated=state.events.find(e=>e.id===eventId);if(ready(updated)){openCompletion(eventId);}else toast('Equipment progress saved.');}catch(e){busy=false;await loadState(false).catch(()=>{});render();if(modal?.type==='detail')renderDetail();toast(e.message,true);}}
function updateClocks(){for(const node of $$('[data-countdown]')){const event=state.events.find(e=>e.id===node.dataset.countdown);if(event){node.textContent=countdown(event);node.classList.toggle('late',!event.completion&&deadline(event)<currentTime());}}}
document.addEventListener('click',async e=>{
  const trigger=e.target.closest('[data-act]');if(!trigger||trigger.disabled||busy)return;const action=trigger.dataset.act,id=trigger.dataset.id;
  try {
    if(action==='navigate'){page=trigger.dataset.page;search='';filter='all';mode='events';render();}
    else if(action==='mode'){mode=trigger.dataset.mode;render();}
    else if(action==='logout'){await api('/api/logout',{method:'POST'});session.user=null;session.setupRequired=false;disconnect();closeModal();renderLogin();}
    else if(action==='close-modal')closeModal();
    else if(action==='event')openEvent(id);
    else if(action==='new-event')openEditor();
    else if(action==='edit-event')openEditor(state.events.find(e=>e.id===id));
    else if(action==='import')openImport(id||null);
    else if(action==='edit-equipment')openEquipment(id);
    else if(action==='add-equipment-row')$('#equipment-rows').insertAdjacentHTML('beforeend',equipmentEditRow());
    else if(action==='remove-equipment-row')trigger.closest('[data-equipment-row]').remove();
    else if(action==='complete')openCompletion(id);
    else if(action==='suggest'){const body=eventFormBody($('#event-form'));renderSuggestions(localSuggestions(body));toast('Suggestions updated. Select the stewards you want to assign.');}
    else if(action==='add-rule')openRule();
    else if(action==='edit-rule')openRule(id);
    else if(action==='delete-rule'){const rule=state.rules.find(r=>r.id===id);modal={type:'delete-rule',id};setModal(modalHead(`Delete ${esc(rule.name)} rule?`,'Existing event checklists will remain intact.')+`<div class="modal-body"><p class="muted" style="font-size:13px">New events will no longer receive this requirement. You can add the rule again later.</p></div><footer class="modal-footer"><button class="button secondary" data-act="close-modal">Cancel</button><button class="button danger" data-act="confirm-delete-rule" data-id="${id}">Delete rule</button></footer>`);}
    else if(action==='confirm-delete-rule'){await api('/api/rules',{method:'PUT',body:{rules:state.rules.filter(r=>r.id!==id)}});closeModal();await loadState();toast('Rule deleted.');}
    else if(action==='export-rules')exportRules();
    else if(action==='import-rules')openRuleImport();
    else if(action==='download-template')download('equipment-rules-template.csv','name,eventType,basis,quantity,per,unit,note\r\nChafers,buffet,dishes,1,1,each,Confirm quantity per hot dish\r\nDinner plates,buffet,guests,1,1,each,Confirm guest quantity\r\n','text/csv');
    else if(action==='confirm-rule-import'){await api('/api/rules',{method:'PUT',body:{rules:[...state.rules,...modal.importedRules]}});closeModal();await loadState();toast('Equipment rules imported.');}
    else if(action==='export-audit')download('banquet-audit.json',JSON.stringify({exportedAt:new Date().toISOString(),timezone:timezone(),scope:'Most recent 500 records',records:state.audit},null,2),'application/json');
    else if(action==='add-user')openUser();
    else if(action==='edit-user')openUser(id);
    else if(action==='notifications')openNotifications();
    else if(action==='acknowledge-change'){await api('/api/notifications/read',{method:'POST',body:{id}});await loadState(false);render();renderDetail();}
    else if(action==='notification'){await api('/api/notifications/read',{method:'POST',body:{id}});await loadState(false);render();if(state.events.some(ev=>ev.id===trigger.dataset.event))openEvent(trigger.dataset.event);else{openNotifications();toast('This event is no longer assigned to you.');}}
  }catch(err){toast(err.message,true);}
});
document.addEventListener('change',async e=>{
  if(e.target.matches('[data-date]')){date=e.target.value||localDate(currentTime());render();}
  if(e.target.matches('[data-filter]')){filter=e.target.value;render();}
  if(e.target.matches('[data-check-item]')){const event=state.events.find(ev=>ev.id===e.target.dataset.event),item=event.equipment.find(i=>i.id===e.target.dataset.checkItem);await saveChecklist(event.id,item.id,e.target.checked?item.required:0);}
  if(e.target.matches('[data-ready-item]')){await saveChecklist(e.target.dataset.event,e.target.dataset.readyItem,Number(e.target.value));}
  if(e.target.id==='completion-photo'){try{const file=e.target.files[0];if(file){const blob=await compressPhoto(file);if(modal?.type!=='complete')return;modal.photo=blob;const url=URL.createObjectURL(blob);$('#photo-preview').innerHTML=`<img class="photo-preview" src="${url}" alt="Preview of your setup photo">`;$('.photo-preview').onload=()=>URL.revokeObjectURL(url);}}catch(err){$('#modal-error').textContent='This photo could not be opened. Choose a JPEG or take a new photo.';}}
  if(e.target.closest('#event-form'))updateDeadlinePreview();
});
document.addEventListener('input',e=>{
  if(e.target.matches('[data-search]')){search=e.target.value;const start=e.target.selectionStart;$('#page-content').innerHTML=pageContent();const next=$('[data-search]');next.focus();next.setSelectionRange(start,start);}
  if(e.target.closest('#event-form'))updateDeadlinePreview();
});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target;if(busy)return;const error=$(form.id==='auth-form'?'#auth-error':'#modal-error',form);if(error)error.textContent='';const buttons=$$('button[type="submit"]',form);buttons.forEach(b=>b.disabled=true);busy=true;
  try {
    if(form.id==='auth-form'){const body=Object.fromEntries(new FormData(form));const result=await api(session.setupRequired?'/api/setup':'/api/login',{method:'POST',body});session={...session,...result,setupRequired:false};await loadState(false);bootAuth();}
    else if(form.id==='pdf-form'){const eventId=modal.eventId;const formData=new FormData(form);const button=buttons[0];button.textContent='Reading every page…';const extracted=await readSupervisorPDF(formData.get('file'),message=>button.textContent=message);formData.set('text',extracted.text);formData.set('pages',extracted.pages);formData.set('ocr',String(extracted.ocr));const result=await api('/api/import/pdf',{method:'POST',body:formData});const selected=eventId?state.events.find(ev=>ev.id===eventId):result.existing;if(selected&&result.fields.beo&&result.fields.beo!==selected.beo)throw new Error(`This PDF is BEO ${result.fields.beo}, but the event is ${selected.beo}. Import it as a separate event.`);busy=false;openEditor(selected,result);}
    else if(form.id==='event-form'){const body=eventFormBody(form);const current=modal.event;const path=current?`/api/events/${current.id}${modal.imported?'/revision':''}`:'/api/events';const result=await api(path,{method:current?'PUT':'POST',body});date=localDate(result.event.start);busy=false;closeModal();await loadState();openEvent(result.event.id);toast(current?'Event updated and team alerted.':'Event and equipment checklist created.');}
    else if(form.id==='equipment-form'){const equipment=$$('[data-equipment-row]',form).map(row=>({id:row.dataset.id,name:$('[name="equipment-name"]',row).value,required:Number($('[name="equipment-required"]',row).value),unit:$('[name="equipment-unit"]',row).value}));const id=modal.event.id;await api(`/api/events/${id}/equipment`,{method:'PUT',body:{version:modal.event.version,equipment,reason:new FormData(form).get('reason')}});busy=false;closeModal();await loadState();openEvent(id);toast('Requirements updated and stewards alerted.');}
    else if(form.id==='complete-form'){const file=new FormData(form).get('photo');if(!file?.size)throw new Error('A completion photo is required.');const photo=modal.photo||await compressPhoto(file);const id=modal.event.id;const body=new FormData();body.set('version',modal.event.version);body.set('photo',photo,'setup.jpg');await api(`/api/events/${id}/complete`,{method:'POST',body});busy=false;closeModal();await loadState();openEvent(id);toast('Setup complete. Photo and audit record saved.');}
    else if(form.id==='rule-form'){const f=Object.fromEntries(new FormData(form));const rule={...f,id:modal.rule.id,quantity:Number(f.quantity),per:Number(f.per)};await api('/api/rules',{method:'PUT',body:{rules:modal.rule.id?state.rules.map(r=>r.id===modal.rule.id?rule:r):[...state.rules,rule]}});busy=false;closeModal();await loadState();toast('Equipment rule saved.');}
    else if(form.id==='user-form'){const body=Object.fromEntries(new FormData(form));if(modal.user)body.active=body.active==='1';await api(modal.user?`/api/users/${modal.user.id}`:'/api/users',{method:modal.user?'PATCH':'POST',body});busy=false;closeModal();await loadState();toast('Team account saved.');}
    else if(form.id==='timezone-form'){await api('/api/settings',{method:'PUT',body:Object.fromEntries(new FormData(form))});await loadState();toast('Venue timezone saved.');}
    else if(form.id==='rule-import-form'){const file=new FormData(form).get('file');if(file.size>1024*1024)throw new Error('CSV must be smaller than 1 MB.');const csv=parseCSV((await file.text()).replace(/^\uFEFF/,''));const keys=csv.shift()?.map(x=>x.trim());for(const k of ['name','eventType','basis','quantity','per','unit'])if(!keys?.includes(k))throw new Error(`CSV is missing the ${k} column.`);if(!csv.length||csv.length+state.rules.length>200)throw new Error('Import 1–200 rules, including existing rules.');const imported=csv.map(row=>{const item=Object.fromEntries(keys.map((k,i)=>[k,row[i]?.trim()||'']));item.quantity=Number(item.quantity);item.per=Number(item.per);if(!item.name||!item.eventType||!['fixed','guests','dishes'].includes(item.basis)||!Number.isInteger(item.quantity)||item.quantity<1||!Number.isInteger(item.per)||item.per<1)throw new Error('A rule has an invalid name, event type, basis or quantity.');return item;});modal.importedRules=imported;$('#rule-import-preview').innerHTML=`<div class="notice">${imported.length} rules ready to add. Existing rules will remain.</div><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Type</th><th>Quantity</th></tr></thead><tbody>${imported.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.eventType)}</td><td>${ruleDescription(r)}</td></tr>`).join('')}</tbody></table></div><button class="button" type="button" data-act="confirm-rule-import" style="margin-top:15px">Confirm import</button>`;}
  }catch(err){if(error&&error.isConnected)error.textContent=err.message;else toast(err.message,true);}
  finally{busy=false;buttons.forEach(b=>{b.disabled=false;if(form.id==='pdf-form')b.textContent='Read all pages →';});}
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&modal&&!busy){closeModal();return;}
  if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-act]')){e.preventDefault();e.target.click();}
  if(e.key==='Tab'&&modalRoot.firstChild){const elements=$$('button:not(:disabled),a[href],input:not(:disabled),select,textarea,[tabindex="0"]',modalRoot).filter(node=>node.offsetParent!==null);if(!elements.length)return;const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
setInterval(updateClocks,1000);
setInterval(()=>{if(session.user&&!busy&&!live)loadState().catch(()=>{live=false;updateLive();});},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session.user)loadState().catch(()=>{});});
try{session=await api('/api/session');if(session.user){await loadState(false);bootAuth();}else renderLogin();}catch(err){app.innerHTML=`<div class="boot"><span class="brand-icon">B</span><p>Could not connect to Banquet Steward.</p><button class="button" data-act="reload">Try again</button></div>`;app.addEventListener('click',()=>location.reload(),{once:true});}
